SELECT CASE WHEN budget >= 3886000 THEN 'high' WHEN budget >= 1809000 THEN 'mid' ELSE 'low' END budget_bucket, SORT_ARRAY(COLLECT_SET(dept_name)) dept_name_list, SUM(CASE WHEN dept_name = 'Engineering' THEN 1 ELSE 0 END) engineering_count FROM departments WHERE budget < 1580000 AND dept_name != 'Engineering' AND location = 'London' GROUP BY CASE WHEN budget >= 3886000 THEN 'high' WHEN budget >= 1809000 THEN 'mid' ELSE 'low' END;
